@Override
	public void render(ManaShield entity, float yaw, float tickDelta, PoseStack poseStack, MultiBufferSource vertices, int light) {
		float alpha = Mth.clamp(((entity.getMaxAge() - entity.getTrueAge()) - tickDelta) / 20f, 0, 1);

		poseStack.pushPose();
		poseStack.translate(0, 2, 0);
		poseStack.mulPose(Axis.XN.rotationDegrees(90));
		poseStack.mulPose(Axis.ZP.rotationDegrees((entity.tickCount + tickDelta) * 0.25f));
		poseStack.scale(3 * alpha, 3 * alpha, 3 * alpha);
		drawIcosahedron(poseStack, vertices.getBuffer(LAYER), ArcanusHelper.getMagicColor(entity), alpha, light, OverlayTexture.NO_OVERLAY);
		poseStack.popPose();
	}

public static void drawIcosahedron(PoseStack poseStack, VertexConsumer consumer, Color color, float alpha, int light, int overlay) {
		Matrix4f matrix4f = poseStack.last().pose();
		float r = color.redF() * alpha;
		float g = color.greenF() * alpha;
		float b = color.blueF() * alpha;

		for(Vector3i face : FACES) {
			Vector3f vert1 = ManaShieldRenderer.VERTICES.get(face.x);
			Vector3f vert2 = ManaShieldRenderer.VERTICES.get(face.y);
			Vector3f vert3 = ManaShieldRenderer.VERTICES.get(face.z);
			Vector3f u = new Vector3f(vert2.x - vert1.x, vert2.y - vert1.y, vert2.z - vert1.z);
			Vector3f v = new Vector3f(vert3.x - vert1.x, vert3.y - vert1.y, vert3.z - vert1.z);
			Vector3f normal = u.cross(v);

			consumer.addVertex(matrix4f, vert1.x, vert1.y, vert1.z).setColor(r, g, b, 1f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), normal.x, normal.y, normal.z);
			consumer.addVertex(matrix4f, vert2.x, vert2.y, vert2.z).setColor(r, g, b, 1f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), normal.x, normal.y, normal.z);
			consumer.addVertex(matrix4f, vert3.x, vert3.y, vert3.z).setColor(r, g, b, 1f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), normal.x, normal.y, normal.z);
		}
	}

private static void renderWardedBlock(PoseStack poseStack, MultiBufferSource buffer, Level level, Vec3 cameraPos, BlockPos blockPos, float alpha) {
		VertexConsumer consumer = buffer.getBuffer(WARDED_BLOCK);
		Vec3 pos = Vec3.atCenterOf(blockPos);

		poseStack.pushPose();
		poseStack.translate(pos.x() - cameraPos.x(), pos.y() - cameraPos.y(), pos.z() - cameraPos.z());
		poseStack.scale(1.001f, 1.001f, 1.001f);
		poseStack.translate(-0.5, -0.5, -0.5);

		PoseStack.Pose pose = poseStack.last();
		Matrix4f matrix4f = pose.pose();
		Color color = ArcanusHelper.getMagicColor(ArcanusComponents.getWardedBlocks(level.getChunk(blockPos)).get(blockPos));
		int light = level.getMaxLocalRawBrightness(blockPos);
		int overlay = OverlayTexture.NO_OVERLAY;
		float r = Mth.clamp(color.redF() * alpha, 0f, 1f);
		float g = Mth.clamp(color.greenF() * alpha, 0f, 1f);
		float b = Mth.clamp(color.blueF() * alpha, 0f, 1f);

		color = Color.fromFloatsRGB(r, g, b);

		for(Direction direction : Direction.values()) {
			BlockPos posToSide = blockPos.relative(direction);
			BlockState stateToSide = level.getBlockState(posToSide);

			if(stateToSide.isFaceSturdy(level, posToSide, direction.getOpposite(), SupportType.FULL) || ArcanusComponents.isBlockWarded(level, posToSide))
				continue;

			switch(direction) {
				case SOUTH ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 0f, 1f, 1f, 1f, 1f, 1f, color, light, overlay, pose, Direction.SOUTH);
				case NORTH ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 1f, 0f, 0f, 0f, 0f, 0f, color, light, overlay, pose, Direction.NORTH);
				case EAST ->
					ArcanusClient.renderQuad(matrix4f, consumer, 1f, 1f, 1f, 0f, 0f, 1f, 1f, 0f, color, light, overlay, pose, Direction.EAST);
				case WEST ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 0f, 0f, 1f, 0f, 1f, 1f, 0f, color, light, overlay, pose, Direction.WEST);
				case DOWN ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 0f, 0f, 0f, 0f, 1f, 1f, color, light, overlay, pose, Direction.DOWN);
				case UP ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 1f, 1f, 1f, 1f, 0f, 0f, color, light, overlay, pose, Direction.UP);
			}
		}

		poseStack.popPose();
	}

@Override
    public void render(MagibladeWardenHeadVisualEntity entity, float yaw, float tickDelta,
                       MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        if (shouldSkipFirstPersonOwner(entity)) {
            return;
        }

        float spawnFade = MathHelper.clamp((entity.age + tickDelta) / 8.0F, 0.0F, 1.0F);
        float dismissFade = entity.isDismissing()
                ? 1.0F - MathHelper.clamp(
                (entity.getDismissTicks() + tickDelta)
                        / MagibladeWardenHeadVisualEntity.DISMISS_DURATION_TICKS,
                0.0F,
                1.0F)
                : 1.0F;
        float fade = spawnFade * dismissFade;
        if (fade <= 0.01F) {
            return;
        }

        float renderYaw = MathHelper.lerpAngleDegrees(tickDelta, entity.prevYaw, entity.getTargetYaw());
        float renderPitch = MathHelper.lerp(tickDelta, entity.prevPitch, entity.getTargetPitch());
        float pulseProgress = entity.getShotPulseTicks() <= 0
                ? 0.0F
                : 1.0F - (entity.getShotPulseTicks() - tickDelta) / 8.0F;
        float shotPulse = MathHelper.sin(MathHelper.clamp(pulseProgress, 0.0F, 1.0F) * MathHelper.PI);
        float appearScale = 0.72F + 0.28F * spawnFade;
        float dismissScale = 0.55F + 0.45F * dismissFade;
        float scale = entity.getScale() * appearScale * dismissScale * (1.0F + shotPulse * 0.1F);

        animateTendrils(entity, tickDelta, shotPulse);

        Vec3d entityPosition = interpolatedPosition(entity, tickDelta);
        Vec3d renderAnchor = getRenderAnchor(entity, tickDelta);
        Vec3d renderOffset = renderAnchor.subtract(entityPosition);

        matrices.push();
        matrices.translate(renderOffset.x, renderOffset.y, renderOffset.z);
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F - renderYaw));
        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(-renderPitch));
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(180.0F));
        matrices.scale(scale, scale, scale);
        matrices.translate(0.0F, -0.5F, -shotPulse * 0.08F);

        int alpha = MathHelper.clamp((int) (255.0F * fade), 0, 255);
        int color = alpha << 24 | 0xFFFFFF;

        VertexConsumer baseVertices =
                vertexConsumers.getBuffer(RenderLayer.getEntityTranslucent(BASE_TEXTURE));
        this.head.render(matrices, baseVertices, light, OverlayTexture.DEFAULT_UV, color);

        VertexConsumer glowVertices =
                vertexConsumers.getBuffer(RenderLayer.getEntityTranslucentEmissive(BIOLUMINESCENT_TEXTURE));
        this.head.render(
                matrices,
                glowVertices,
                LightmapTextureManager.MAX_LIGHT_COORDINATE,
                OverlayTexture.DEFAULT_UV,
                color
        );
        matrices.pop();
    }

@Override
	public void renderParticle(BufferBuilder buff, Entity entityIn, float partialTicks, float rx, float rz, float ryz, float rxy, float rxz) {
		float minU = (float)this.particleTextureIndexX / 16.0F;
		float maxU = minU + 0.0624375F;
		float minV = (float)this.particleTextureIndexY / 16.0F;
		float maxV = minV + 0.0624375F;
		float scale = 0.1F * this.particleScale * 2;

		if (this.particleTexture != null) {
			minU = this.particleTexture.getMinU();
			maxU = this.particleTexture.getMaxU();
			minV = this.particleTexture.getMinV();
			maxV = this.particleTexture.getMaxV();
		}

		float rpx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float rpy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rpz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);
		int brightness = this.getBrightnessForRender(partialTicks);
		int lightmapX = brightness >> 16 & 65535;
		int lightmapY = brightness & 65535;

		Vec3d normal = new Vec3d(this.face.getDirectionVec());
		Vec3d perpendicular;
		switch(this.face) {
		case UP:
			perpendicular = new Vec3d(1, 0, 0);
			break;
		case DOWN:
			perpendicular = new Vec3d(-1, 0, 0);
			break;
		default:
			perpendicular = new Vec3d(0, 1, 0);
		}
		Vec3d perpendicular2 = perpendicular.crossProduct(normal);

		double yOffset = 0.125D;
		Vec3d[] vertices = new Vec3d[] {perpendicular.add(perpendicular2.scale(-1)).add(perpendicular.scale(yOffset)).scale(scale), perpendicular.scale(-1).add(perpendicular2.scale(-1)).add(perpendicular.scale(yOffset)).scale(scale), perpendicular.scale(-1).add(perpendicular2).add(perpendicular.scale(yOffset)).scale(scale), perpendicular.add(perpendicular2).add(perpendicular.scale(yOffset)).scale(scale)};

		if (this.particleAngle != 0.0F) {
			float f8 = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
			float f9 = MathHelper.cos(f8 * 0.5F);
			float f10 = MathHelper.sin(f8 * 0.5F) * this.face.getXOffset();
			float f11 = MathHelper.sin(f8 * 0.5F) * this.face.getYOffset();
			float f12 = MathHelper.sin(f8 * 0.5F) * this.face.getZOffset();
			Vec3d vec3d = new Vec3d((double)f10, (double)f11, (double)f12);

			for (int l = 0; l < 4; ++l) {
				vertices[l] = vec3d.scale(2.0D * vertices[l].dotProduct(vec3d)).add(vertices[l].scale((double)(f9 * f9) - vec3d.dotProduct(vec3d))).add(vec3d.crossProduct(vertices[l]).scale((double)(2.0F * f9)));
			}
		}

		buff.pos((double)rpx + vertices[0].x, (double)rpy + vertices[0].y, (double)rpz + vertices[0].z).tex((double)maxU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[1].x, (double)rpy + vertices[1].y, (double)rpz + vertices[1].z).tex((double)maxU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[2].x, (double)rpy + vertices[2].y, (double)rpz + vertices[2].z).tex((double)minU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[3].x, (double)rpy + vertices[3].y, (double)rpz + vertices[3].z).tex((double)minU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
	}

@Override
	public void render(PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, AbstractClientPlayer player, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float netHeadPitch) {
		if (!player.isInvisible() && AoAConfigs.CLIENT.showPlayerHalos.get()) {
			PlayerHaloManager.getHaloForRender(player.getUUID()).ifPresent(halo -> {
				if (halo == HaloTypes.TSLAT) {
					VertexConsumer vertexConsumer = bufferSource.getBuffer(TSLAT_HALO_RENDER_TYPE);

					this.model.root.copyFrom(getParentModel().getHead());
					this.model.renderToBuffer(poseStack, vertexConsumer, LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, ColourUtil.ARGB(0, 0, 0, 0.1f));

					return;
				}

				float red = 0;
				float green = 0;
				float blue = 0;

				switch (halo) {
					case DONATOR -> {
						red = 1;
						green = 1;
					}
					case SUPER_DONATOR -> red = 1;
					case STAFF -> {
						red = 0.6f;
						green = 1;
						blue = 1;
					}
					case WIKI_EDITOR -> blue = 1;
				}

				RenderSystem.enableBlend();
				RenderSystem.disableDepthTest();
				this.model.root.copyFrom(getParentModel().getHead());
				this.model.renderToBuffer(poseStack, bufferSource.getBuffer(RenderType.entityTranslucent(getTextureLocation(player))), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, ColourUtil.ARGB(red, green, blue, 0.1f));
				RenderSystem.enableDepthTest();
				RenderSystem.disableBlend();
			});
		}
	}
